UPDATE TBL_RESUME_M SET address_sq =
   #{dto.address.addressSq}, resume_ttl = #{dto.resumeTtl}, resume_nm = #{dto.resumeNm},
   resume_birth_dt = #{dto.resumeBirthDt}, resume_phone_num = #{dto.resumePhoneNum}, resume_email =
   #{dto.resumeEmail}, resume_greeting_txt = #{dto.resumeGreetingTxt}, resume_is_notification_yn =
   #{dto.resumeIsNotificationYn}, resume_is_representative_yn = #{dto.resumeIsRepresentativeYn}
   WHERE resume_sq = #{dto.resumeSq}

