SELECT
   address_sq, zonecode, address, detail_address AS detailAddress, sigungu, latitude, longitude,
   area_code_sq AS areaCodeSq FROM TBL_ADDRESS_S WHERE address_sq = #{addressSq}

SELECT project_history_skill_sq, project_history_sq, skill_tag_sq, parent_skill_tag_sq,
skill_tag_lvl, skill_tag_nm FROM TBL_RESUME_PROJECT_HISTORY_SKILL_TAG_S WHERE project_history_sq
= #{projectHistorySq}

SELECT certification_sq, resume_sq, certificate_cd AS certificationCd, certification_nm AS
certificationNm, certification_issuer_nm AS certificationIssuerNm FROM
TBL_RESUME_CERTIFICATION_S WHERE resume_sq = #{resumeSq}

SELECT
   resume_skill_sq, resume_sq, skill_tag_sq, parent_skill_tag_sq, skill_tag_lvl, skill_tag_nm FROM
   TBL_RESUME_SKILL_TAG_S WHERE resume_sq = #{resumeSq}

SELECT
   career_sq, resume_sq, career_company_nm, career_department_nm, career_position_nm,
   career_start_dt, career_end_dt FROM TBL_RESUME_CAREER_S WHERE resume_sq = #{resumeSq}

SELECT project_history_skill_sq, project_history_sq,
skill_tag_sq,parent_skill_tag_sq,skill_tag_lvl,skill_tag_nm FROM
TBL_RESUME_PROJECT_HISTORY_SKILL_TAG_S WHERE project_history_sq = #{projectHistorySq}

SELECT
   resume_skill_sq, resume_sq,skill_tag_sq,parent_skill_tag_sq,skill_tag_lvl,skill_tag_nm FROM
   TBL_RESUME_SKILL_TAG_S WHERE resume_sq = #{resumeSq}

SELECT
   f.file_sq, f.file_original_nm, f.file_save_nm, f.file_typ,f.file_size FROM TBL_COMMON_FILE_S f
   INNER JOIN TBL_RESUME_ATTACHMENT_S p ON f.file_sq = p.file_sq WHERE p.resume_sq = #{resumeSq}

SELECT
   f.file_sq, f.file_original_nm, f.file_save_nm, f.file_typ,f.file_size FROM TBL_COMMON_FILE_S f
   INNER JOIN TBL_RESUME_PROFILE_IMAGE_S p ON f.file_sq = p.file_sq WHERE p.resume_sq = #{resumeSq}
